#!/usr/bin/env node
// Build the estate index in README.md from estate.json and repos/*/meta.json.
// The index sits between the BEGIN and END markers; the rest of README.md is hand-written.
// Usage: node build-index.mjs           rewrite the index in README.md
//        node build-index.mjs --check   exit 1 if the index is stale (CI)
import { writeFileSync } from "node:fs";
import { join } from "node:path";
import { formerNamesText, loadEstate, readDocsFile, replaceMarked, root } from "./estate.mjs";

const BEGIN = "<!-- BEGIN estate index: generated by .github/scripts/build-index.mjs from estate.json and repos/*/meta.json. Do not edit by hand. -->";
const END = "<!-- END estate index -->";

const check = process.argv.includes("--check");
const { estate, areas, count, errors } = loadEstate();

// One list item per repo: name and description, then a hard line break ("\") and the links.
// A list, not a table: tables overflow on narrow screens and misalign across areas.
function item({ name, description, formerNames, sha, date, source }) {
  const commit = `[\`${sha.slice(0, 7)}\`](${source}/commit/${sha})`;
  const links = [
    `[Viewer](${estate.siteUrl}${name}/)`,
    `[Onboarding](repos/${name}/ONBOARDING.md)`,
    `[Glossary](repos/${name}/GLOSSARY.md)`,
    `[README](repos/${name}/README.md)`,
    `[Source](${source})`,
    `Snapshot ${date} at ${commit}`,
  ].join(" · ");
  const former = formerNamesText(formerNames, (n) => `\`${n}\``);
  return `- **[${name}](repos/${name}/)**: ${description}${former}\\\n  ${links}`;
}

const sections = areas.map((area) => {
  const lines = [`### ${area.title}`, ""];
  if (area.intro) lines.push(area.intro, "");
  lines.push(...area.repos.map(item));
  if (area.seeAlso) lines.push("", `Go deeper: ${area.seeAlso.map((l) => `[${l.text}](${l.url})`).join(" · ")}`);
  return lines.join("\n");
});

const MARKERS = { begin: BEGIN, end: END, what: "estate index" };
const readme = readDocsFile("README.md", errors);
const next = readme === null ? null : replaceMarked("README.md", readme, MARKERS, sections.join("\n\n"), errors);

if (errors.length) {
  for (const e of errors) console.error(`error: ${e}`);
  process.exit(1);
}

if (check) {
  if (next !== readme) {
    console.error("error: the README.md estate index is stale. Run: node .github/scripts/build-index.mjs");
    process.exit(1);
  }
  console.log(`estate index is current (${count} repos)`);
} else {
  writeFileSync(join(root, "README.md"), next);
  console.log(`wrote the estate index to README.md (${count} repos)`);
}
